import {Permissions} from 'mattermost-redux/constants';
import {getConfig} from 'mattermost-redux/selectors/entities/general';
import {haveIChannelPermission, haveISystemPermission} from 'mattermost-redux/selectors/entities/roles';

import {getChannelSettingsTabs} from 'selectors/plugins';

import Constants from 'utils/constants';

import type {GlobalState} from 'types/store';

/**
 * Selector to determine if a user has access to any tab in the channel settings modal
 * Returns true if the user has permission to access at least one built-in tab or visible plugin tab
 * Note: This does not check license requirements - those should be handled by the calling component
 */
export function canAccessChannelSettings(state: GlobalState, channelId: string): boolean {
    const channel = state.entities.channels.channels[channelId];
    if (!channel) {
        return false;
    }

    const config = getConfig(state);
    const isDMAndGMAutotranslationRestricted = config?.RestrictDMAndGMAutotranslation === 'true';
    const isAutoTranslationEnabled = config?.EnableAutoTranslation === 'true';
    const isSharedChannelsEnabled = config?.ExperimentalSharedChannels === 'true';
    const hasVisiblePluginTabs = getChannelSettingsTabs(state).some((registration) => registration.shouldRender?.(state, channel) ?? true);
    const isDM = channel.type === Constants.DM_CHANNEL;
    const isGM = channel.type === Constants.GM_CHANNEL;

    // For DM and GM: allow Channel Settings when auto-translation is enabled and
    // DM/GM restriction is disabled, or when a plugin contributes a visible tab.
    if (isDM || isGM) {
        const builtInDmGmAccess = isAutoTranslationEnabled && !isDMAndGMAutotranslationRestricted;
        return builtInDmGmAccess || hasVisiblePluginTabs;
    }

    const isPrivate = channel.type === Constants.PRIVATE_CHANNEL;
    const isDefaultChannel = channel.name === Constants.DEFAULT_CHANNEL;

    // Get the team ID from the channel
    const teamId = channel.team_id;

    // Info tab permissions
    const infoPermission = isPrivate ? Permissions.MANAGE_PRIVATE_CHANNEL_PROPERTIES : Permissions.MANAGE_PUBLIC_CHANNEL_PROPERTIES;

    const hasInfoPermission = haveIChannelPermission(
        state,
        teamId,
        channelId,
        infoPermission,
    );

    // Configuration tab (banner) permissions
    const bannerPermission = isPrivate ? Permissions.MANAGE_PRIVATE_CHANNEL_BANNER : Permissions.MANAGE_PUBLIC_CHANNEL_BANNER;

    const hasBannerPermission = haveIChannelPermission(
        state,
        teamId,
        channelId,
        bannerPermission,
    );

    // Configuration tab (translation) permissions
    const translationPermission = isPrivate ? Permissions.MANAGE_PRIVATE_CHANNEL_AUTO_TRANSLATION : Permissions.MANAGE_PUBLIC_CHANNEL_AUTO_TRANSLATION;
    const hasTranslationPermission = haveIChannelPermission(
        state,
        teamId,
        channelId,
        translationPermission,
    );

    // Configuration tab (shared channels) permissions
    const hasSharedChannelsPermission = isSharedChannelsEnabled &&
        haveISystemPermission(state, {permission: Permissions.MANAGE_SHARED_CHANNELS});

    // Archive tab permissions
    const archivePermission = isPrivate ? Permissions.DELETE_PRIVATE_CHANNEL : Permissions.DELETE_PUBLIC_CHANNEL;

    const hasArchivePermission = !isDefaultChannel && haveIChannelPermission(
        state,
        teamId,
        channelId,
        archivePermission,
    );

    // User can access channel settings if they have permission for at least one tab
    return hasInfoPermission || hasBannerPermission || hasTranslationPermission || hasSharedChannelsPermission || hasArchivePermission || hasVisiblePluginTabs;
}
